"use client";

import * as React from "react";
import { ScrollArea as ScrollAreaPrimitive } from "@base-ui/react/scroll-area";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Margin ScrollArea: content that scrolls inside its own box, with a thin
 * hairline-grey thumb that shows only while the pointer is over the box or
 * the content moves.
 */
const ScrollArea = React.forwardRef<HTMLDivElement, WithClassName<ScrollAreaPrimitive.Root.Props>>(
  ({ className, children, ...props }, ref) => (
    <ScrollAreaPrimitive.Root
      data-slot="scroll-area"
      ref={ref}
      className={cn("relative overflow-hidden", className)}
      {...props}
    >
      <ScrollAreaPrimitive.Viewport
        data-slot="scroll-area-viewport"
        className="size-full rounded-[inherit] outline-none focus-visible:ring-3 focus-visible:ring-ring"
      >
        <ScrollAreaPrimitive.Content>{children}</ScrollAreaPrimitive.Content>
      </ScrollAreaPrimitive.Viewport>
      <ScrollBar />
      <ScrollAreaPrimitive.Corner data-slot="scroll-area-corner" />
    </ScrollAreaPrimitive.Root>
  ),
);
ScrollArea.displayName = "ScrollArea";

/** One scrollbar for a ScrollArea; add `orientation="horizontal"` for a sideways one. */
const ScrollBar = React.forwardRef<
  HTMLDivElement,
  WithClassName<ScrollAreaPrimitive.Scrollbar.Props>
>(({ className, orientation = "vertical", ...props }, ref) => (
  <ScrollAreaPrimitive.Scrollbar
    data-slot="scroll-area-scrollbar"
    ref={ref}
    orientation={orientation}
    className={cn(
      "flex touch-none select-none p-0.5 opacity-0 transition-opacity duration-base ease-(--ease-out)",
      "data-[hovering]:opacity-100 data-[scrolling]:opacity-100",
      "data-[orientation=vertical]:h-full data-[orientation=vertical]:w-2",
      "data-[orientation=horizontal]:h-2 data-[orientation=horizontal]:flex-col",
      className,
    )}
    {...props}
  >
    <ScrollAreaPrimitive.Thumb
      data-slot="scroll-area-thumb"
      className="relative flex-1 rounded-full bg-input transition-colors duration-fast hover:bg-muted-foreground/50"
    />
  </ScrollAreaPrimitive.Scrollbar>
));
ScrollBar.displayName = "ScrollBar";

export { ScrollArea, ScrollBar };
